def is_digits(s):
    return len(s) > 0 and s.isdigit()

def is_valid_integer(s):
    if not s:
        return False
    i = 1 if s[0] in '+-' else 0
    return is_digits(s[i:])

def is_valid_decimal(s):
    if not s:
        return False
    i = 1 if s[0] in '+-' else 0
    rest = s[i:]
    if not rest:
        return False
    if '.' in rest:
        parts = rest.split('.')
        if len(parts) != 2:
            return False
        int_part, frac_part = parts
        if not int_part and not frac_part:                # a lone dot is not enough
            return False
        if int_part and not is_digits(int_part):
            return False
        if frac_part and not is_digits(frac_part):
            return False
        return True
    return is_digits(rest)

def is_number(s):
    lower = s.lower()
    if 'e' in lower:
        idx = lower.index('e')
        mantissa, exponent = s[:idx], s[idx + 1:]           # split into two independent parts
        return is_valid_decimal(mantissa) and is_valid_integer(exponent)
    return is_valid_decimal(s)

