    static boolean isDigits(String s) {
        if (s.isEmpty()) return false;
        for (char c : s.toCharArray()) if (!Character.isDigit(c)) return false;
        return true;
    }

    static boolean isValidInteger(String s) {
        if (s.isEmpty()) return false;
        int i = (s.charAt(0) == '+' || s.charAt(0) == '-') ? 1 : 0;
        return isDigits(s.substring(i));
    }

    static boolean isValidDecimal(String s) {
        if (s.isEmpty()) return false;
        int i = (s.charAt(0) == '+' || s.charAt(0) == '-') ? 1 : 0;
        String rest = s.substring(i);
        if (rest.isEmpty()) return false;
        if (rest.contains(".")) {
            String[] parts = rest.split("\\.", -1);
            if (parts.length != 2) return false;
            String intPart = parts[0], fracPart = parts[1];
            if (intPart.isEmpty() && fracPart.isEmpty()) return false;   // a lone dot is not enough
            if (!intPart.isEmpty() && !isDigits(intPart)) return false;
            if (!fracPart.isEmpty() && !isDigits(fracPart)) return false;
            return true;
        }
        return isDigits(rest);
    }

    static boolean isNumber(String s) {
        String lower = s.toLowerCase();
        int idx = lower.indexOf('e');
        if (idx != -1) {
            String mantissa = s.substring(0, idx), exponent = s.substring(idx + 1);  // split into two parts
            return isValidDecimal(mantissa) && isValidInteger(exponent);
        }
        return isValidDecimal(s);
    }
}

