#include <bits/stdc++.h>
using namespace std;

bool isDigits(const string& s) {
    if (s.empty()) return false;
    for (char c : s) if (!isdigit((unsigned char)c)) return false;
    return true;
}

bool isValidInteger(const string& s) {
    if (s.empty()) return false;
    int i = (s[0] == '+' || s[0] == '-') ? 1 : 0;
    return isDigits(s.substr(i));
}

bool isValidDecimal(const string& s) {
    if (s.empty()) return false;
    int i = (s[0] == '+' || s[0] == '-') ? 1 : 0;
    string rest = s.substr(i);
    if (rest.empty()) return false;
    auto dot = rest.find('.');
    if (dot != string::npos) {
        string intPart = rest.substr(0, dot), fracPart = rest.substr(dot + 1);
        if (fracPart.find('.') != string::npos) return false;
        if (intPart.empty() && fracPart.empty()) return false;         // a lone dot is not enough
        if (!intPart.empty() && !isDigits(intPart)) return false;
        if (!fracPart.empty() && !isDigits(fracPart)) return false;
        return true;
    }
    return isDigits(rest);
}

bool isNumber(const string& s) {
    string lower = s;
    for (auto& c : lower) c = tolower(c);
    auto idx = lower.find('e');
    if (idx != string::npos) {
        string mantissa = s.substr(0, idx), exponent = s.substr(idx + 1);   // split into two parts
        return isValidDecimal(mantissa) && isValidInteger(exponent);
    }
    return isValidDecimal(s);
}

