def is_number(s):
    seen_digit = seen_dot = seen_exp = False
    seen_digit_after_exp = True                # true until an exponent marker actually appears
    for i, c in enumerate(s):
        if c.isdigit():
            seen_digit = True
            if seen_exp:
                seen_digit_after_exp = True
        elif c in '+-':
            if i > 0 and s[i - 1].lower() != 'e':          # sign only at start, or right after e/E
                return False
        elif c == '.':
            if seen_dot or seen_exp:                         # at most one dot, and never after an exponent
                return False
            seen_dot = True
        elif c in 'eE':
            if seen_exp or not seen_digit:                   # at most one exponent, and needs a digit before it
                return False
            seen_exp = True
            seen_digit_after_exp = False
        else:
            return False
    return seen_digit and seen_digit_after_exp

